import 'dart:async';
import 'dart:typed_data';
import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:image/image.dart' as pixels;
import 'package:openim_common/openim_common.dart';
import '../utils/protected_crop_geometry.dart';

/// JPEG/PNG crop previews and encoding remain entirely in bounded RAM.
class PrivateCropPage extends StatefulWidget{
 final String source;const PrivateCropPage(this.source,{super.key});
 @override State<PrivateCropPage> createState()=>_PrivateCropState();
}
class _PrivateCropState extends State<PrivateCropPage>{
 Uint8List? bytes;String? error,source,name;bool busy=true;double aspect=1,zoom=1;Offset center=const Offset(.5,.5);Size image=Size.zero;StreamSubscription<void>? invalidated;int generation=0;
 @override void initState(){super.initState();invalidated=NativeLocalVault.invalidated.listen((_){generation++;bytes?.fillRange(0,bytes!.length,0);if(mounted)setState((){bytes=null;busy=false;error='当前图片预览已关闭，请重新授权打开';});});load();}
 Future<void> load()async{final attempt=++generation;try{source=await NativeLocalVault.importSource(widget.source);name=(await NativeLocalVault.sourceInfo(source!))['name'] as String;final data=await NativeLocalVault.readSource(source!);final info=pixels.findDecoderForData(data)?.startDecode(data);if(info==null||info.width.toDouble()*info.height>64000000){data.fillRange(0,data.length,0);throw StateError('Image limit');}if(!mounted||attempt!=generation){data.fillRange(0,data.length,0);return;}setState((){bytes=data;image=Size(info.width.toDouble(),info.height.toDouble());busy=false;});}catch(_){if(mounted&&attempt==generation)setState((){busy=false;error='图片暂不支持安全裁剪，请重试或选择 JPEG/PNG 图片';});}}
 Future<void> save()async{final data=bytes;if(data==null||busy)return;final attempt=generation;setState(()=>busy=true);try{final ext=name!.split('.').last.toLowerCase();if(!['png','jpg','jpeg'].contains(ext))throw StateError('Unsupported crop format');final decoded=pixels.decodeImage(data);if(decoded==null)throw StateError('Image unavailable');final rect=protectedCropRect(image,aspect,zoom,center);final x=rect.left.floor(),y=rect.top.floor();final output=pixels.copyCrop(decoded,x:x,y:y,width:math.max(1,math.min(decoded.width-x,rect.width.round())),height:math.max(1,math.min(decoded.height-y,rect.height.round())));final encoded=Uint8List.fromList(ext=='png'?pixels.encodePng(output):pixels.encodeJpg(output,quality:90));try{final path=await NativeLocalVault.sourceBytes(encoded,name!);if(!mounted||attempt!=generation){await NativeLocalVault.discard(path);return;}Navigator.pop(context,path);}finally{encoded.fillRange(0,encoded.length,0);}}catch(_){if(mounted&&attempt==generation)setState(()=>error='裁剪未完成，仅支持 JPEG/PNG，请重试');}finally{if(mounted&&attempt==generation)setState(()=>busy=false);}}
 @override void dispose(){generation++;invalidated?.cancel();bytes?.fillRange(0,bytes!.length,0);if(source!=null)unawaited(NativeLocalVault.discard(source!).catchError((_){}));super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('裁剪图片'),actions:[TextButton(onPressed:busy?null:save,child:const Text('完成'))]),body:Column(children:[if(busy)const LinearProgressIndicator(),if(error!=null)Text(error!),Expanded(child:LayoutBuilder(builder:(context,bounds){if(bytes==null)return const SizedBox();final scale=math.min(bounds.maxWidth/image.width,bounds.maxHeight/image.height);final origin=Offset((bounds.maxWidth-image.width*scale)/2,(bounds.maxHeight-image.height*scale)/2);final crop=protectedCropRect(image,aspect,zoom,center);return GestureDetector(onPanUpdate:busy?null:(event)=>setState(()=>center=Offset((center.dx+event.delta.dx/(image.width*scale)).clamp(0,1),(center.dy+event.delta.dy/(image.height*scale)).clamp(0,1))),child:Stack(children:[Positioned(left:origin.dx,top:origin.dy,width:image.width*scale,height:image.height*scale,child:Image.memory(bytes!,fit:BoxFit.fill)),Positioned(left:origin.dx+crop.left*scale,top:origin.dy+crop.top*scale,width:crop.width*scale,height:crop.height*scale,child:IgnorePointer(child:DecoratedBox(decoration:BoxDecoration(border:Border.all(color:Colors.white,width:2)))))]));})),DropdownButton<double>(value:aspect,items:const[DropdownMenuItem(value:1,child:Text('1:1')),DropdownMenuItem(value:1.5,child:Text('3:2')),DropdownMenuItem(value:0,child:Text('原始比例')),DropdownMenuItem(value:4/3,child:Text('4:3')),DropdownMenuItem(value:16/9,child:Text('16:9'))],onChanged:busy?null:(value)=>setState(()=>aspect=value??1)),Slider(value:zoom,min:1,max:4,onChanged:busy?null:(value)=>setState(()=>zoom=value)),const Text('拖动选择区域，滑动调整裁剪范围'),const SizedBox(height:16)]));
}
